import "server-only";
import { utcTimestampComparisonKey } from "@/shared/lib/utc-timestamp";
import { currentTransaction, PersistenceFailure } from "@/infrastructure/persistence/postgres/database";
import { NativeRecords, type NativeRecord } from "@/infrastructure/persistence/postgres/native-records";

// The old schema stays readable until the guarded owner-only rebuild commits.
// A partial/unknown installation must never silently select another layout.
const layouts = new WeakMap<object, Promise<boolean>>();
export function singleReceiptPayments(): Promise<boolean> {
  const client = currentTransaction();
  let pending = layouts.get(client);
  if (!pending) {
    pending = (async () => {
      const { rows } = await client.query<{ contract: string | null; columns: string; present: string }>(`SELECT to_regprocedure('stock_operational.receipt_payment_storage_v1()')::text AS contract,
        (SELECT count(*)::text FROM pg_attribute a JOIN (VALUES ('paymentId','text'),('paymentTypeId','text'),('paymentName','text'),('paymentType','text'),('paymentAmount','numeric'),('paymentCreatedAt','timestamp with time zone')) e(name,kind) ON a.attname=e.name AND format_type(a.atttypid,a.atttypmod)=e.kind WHERE a.attrelid='stock_operational.sales_receipts'::regclass AND NOT a.attisdropped) AS columns,
        (SELECT count(*)::text FROM pg_attribute WHERE attrelid='stock_operational.sales_receipts'::regclass AND NOT attisdropped AND attname IN ('paymentId','paymentTypeId','paymentName','paymentType','paymentAmount','paymentCreatedAt')) AS present`);
      if (rows[0]?.contract === null && rows[0]?.present === "0") return false;
      if (!rows[0]?.contract || rows[0]?.columns !== "6" || rows[0]?.present !== "6") throw new PersistenceFailure(503,"Incomplete receipt payment storage. No fallback was attempted.");
      const version = await client.query<{ version: string }>("SELECT stock_operational.receipt_payment_storage_v1() AS version");
      if (version.rows[0]?.version !== "single-receipt-payment-v1") throw new PersistenceFailure(503,"Unsupported receipt payment storage.");
      return true;
    })();
    layouts.set(client, pending);
  }
  return pending;
}

export const singlePaymentReceipts = new NativeRecords("sales_receipts", {
  id: { column: "id", kind: "text" },
  salesDate: { column: "salesDate", kind: "text" },
  accountId: { column: "accountId", kind: "text" },
  receiptNumber: { column: "receiptNumber", kind: "text" },
  receiptType: { column: "receiptType", kind: "text" },
  receiptDate: { column: "receiptDate", kind: "text" },
  createdAt: { column: "createdAt", kind: "timestamp" },
  updatedAt: { column: "updatedAt", kind: "timestamp" },
  cancelledAt: { column: "cancelledAt", kind: "text" },
  syncedAt: { column: "syncedAt", kind: "text" },
  paymentId: { column: "paymentId", kind: "text" },
  paymentTypeId: { column: "paymentTypeId", kind: "text" },
  paymentName: { column: "paymentName", kind: "text" },
  paymentType: { column: "paymentType", kind: "text" },
  paymentAmount: { column: "paymentAmount", kind: "numeric" },
  paymentCreatedAt: { column: "paymentCreatedAt", kind: "timestamp" },
} as const);

export function withReceiptPayment(receipt: NativeRecord, payment?: NativeRecord): NativeRecord {
  return { ...receipt,
    paymentId: payment?.id ?? null,
    paymentTypeId: payment?.paymentTypeId ?? null,
    paymentName: payment?.paymentName ?? null,
    paymentType: payment?.paymentType ?? null,
    paymentAmount: payment?.moneyAmount ?? null,
    ...(payment ? {} : { paymentCreatedAt: null }),
  };
}

// Keep the existing report port/HTTP shape. One receipt yields zero or one
// payment projection; products remain separate and never multiply payments.
export function receiptPaymentRows(receipts: NativeRecord[]): NativeRecord[] {
  return receipts.filter(r => typeof r.paymentId === "string" && r.paymentId !== "").sort((a,b) => {
    const left = String(a.paymentCreatedAt ?? ""), right = String(b.paymentCreatedAt ?? "");
    if (left && !right) return -1; if (!left && right) return 1;
    const l = utcTimestampComparisonKey(left), r = utcTimestampComparisonKey(right);
    return l < r ? -1 : l > r ? 1 : Buffer.compare(Buffer.from(String(a.paymentId)),Buffer.from(String(b.paymentId)));
  }).map(r => ({
    id: r.paymentId, receiptId: r.id, paymentTypeId: r.paymentTypeId,
    paymentName: r.paymentName, paymentType: r.paymentType,
    moneyAmount: r.paymentAmount, syncedAt: r.syncedAt,
  }));
}

import { singleReceiptPayments, singlePaymentReceipts, withReceiptPayment } from "./receipt-payment";
import { PersistenceFailure } from "@/infrastructure/persistence/postgres/database";
import type { NativeRecord } from "@/infrastructure/persistence/postgres/native-records";
import type { Storage } from "./storage";
import "server-only";
import type { ReceiptSyncStore, ReceiptSyncSource, ReceiptSyncBatch } from "../../application/ports/receipt-sync";
import type { ReceiptSource } from "../../application/ports/receipt-source";
import { createSalesReceiptId, createSalesReceiptItemId, createSalesReceiptPaymentId, } from "../../domain/receipt-ids";
import { salesReceiptItemToRecord, salesReceiptPaymentToRecord, salesReceiptToRecord, } from "./receipt-record-mapping";
import { getLoyverseReceiptsForSalesDate } from "../../application/receipts-for-date";
export function createReceiptSync(storage: Storage, account: {
    id: string;
    shopName: string;
    storeId?: string;
    service: ReceiptSource;
}): {
    store: ReceiptSyncStore;
    source: ReceiptSyncSource;
} {
    const batches = new WeakMap<ReceiptSyncBatch, {
        receiptRows: NativeRecord[];
        itemRows: NativeRecord[];
        paymentRows: NativeRecord[];
    }>();
    return {
        source: { async load(salesDate) {
                const receipts = await getLoyverseReceiptsForSalesDate({ loyverseService: account.service, salesDate, storeId: account.storeId });
                return { project(syncedAt) {
                        const receiptRows: NativeRecord[] = [];
                        const itemRows: NativeRecord[] = [];
                        const paymentRows: NativeRecord[] = [];
                        for (const receipt of receipts) {
                            if (!Array.isArray(receipt.payments ?? []) || (receipt.payments?.length ?? 0) > 1) throw new PersistenceFailure(409, "A receipt has multiple or invalid payments. No sales were saved; review the receipt in Loyverse.");
                            const receiptId = createSalesReceiptId(account.id, receipt.receipt_number);
                            receiptRows.push(salesReceiptToRecord({
                                accountId: account.id,
                                id: receiptId,
                                receipt,
                                salesDate,
                                shopName: account.shopName,
                                syncedAt,
                            }));
                            for (const [index, item] of (receipt.line_items || []).entries()) {
                                itemRows.push(salesReceiptItemToRecord({
                                    id: createSalesReceiptItemId(receiptId, item.id, index),
                                    item,
                                    receiptId,
                                    syncedAt,
                                }));
                            }
                            for (const [index, payment] of (receipt.payments || []).entries()) {
                                paymentRows.push(salesReceiptPaymentToRecord({
                                    id: createSalesReceiptPaymentId(receiptId, index),
                                    payment,
                                    paymentIndex: index,
                                    receiptId,
                                    syncedAt,
                                }));
                            }
                        }
                        const batch = { get receiptCount() { return receipts.length; }, get itemCount() { return itemRows.length; }, get paymentCount() { return paymentRows.length; } };
                        batches.set(batch, { receiptRows, itemRows, paymentRows });
                        return batch;
                    } };
            } },
        store: {
            async isComplete(syncId) {
                const syncRows = await storage.salesReceiptSyncs.all();
                return Boolean(syncRows.find(record => record.id === syncId && record.status === "complete"));
            },
            prepare: async () => { await Promise.all([storage.salesReceipts.prepare(), storage.salesReceiptItems.prepare(), storage.salesReceiptPayments.prepare(), storage.salesReceiptSyncs.prepare()]); },
            async append(batch) {
                const { receiptRows, itemRows, paymentRows } = batches.get(batch)!;
                const single = await singleReceiptPayments();
                const payments = new Map(paymentRows.map(row => [row.receiptId, row]));
                for (const record of receiptRows) {
                    if (single) await singlePaymentReceipts.insert(withReceiptPayment(record, payments.get(record.id)));
                    else await storage.salesReceipts.insert(record);
                }
                for (const record of itemRows) await storage.salesReceiptItems.insert(record);
                if (!single) for (const record of paymentRows) await storage.salesReceiptPayments.insert(record);
            },
            async complete(syncId, salesDate, batch, syncedAt) {
                await storage.salesReceiptSyncs.insert({ id: syncId, salesDate, accountId: account.id, shopName: account.shopName, status: "complete", receiptCount: String(batch.receiptCount), itemCount: String(batch.itemCount), paymentCount: String(batch.paymentCount), syncedAt });
            }
        }
    };
}

import { currentTransaction } from "@/infrastructure/persistence/postgres/database";
import { singleReceiptPayments, singlePaymentReceipts, receiptPaymentRows } from "./receipt-payment";
import "server-only";
import type { SalesReader } from "../../application/ports/sales-reader";
import type { Storage } from "./storage";
export type SalesStorage = Pick<Storage, "salesReceipts" | "salesReceiptItems" | "salesReceiptPayments" | "salesReceiptSyncs">;
// Preserve the existing reserved identity without a worksheet/header dependency.
const visible = (records: Awaited<ReturnType<SalesStorage["salesReceipts"]["all"]>>) => records.filter(record => record.id !== "id");
export function createSalesReader(storage: SalesStorage): SalesReader {
  const snapshots = new WeakMap<object, Promise<Awaited<ReturnType<SalesStorage["salesReceipts"]["all"]>>>>();
  function receipts() {
    const client = currentTransaction();let pending = snapshots.get(client);
    if (!pending) { pending = singleReceiptPayments().then(single => single ? singlePaymentReceipts.all() : storage.salesReceipts.all()).then(visible);snapshots.set(client,pending); }
    return pending;
  }
  return { receipts, items: () => storage.salesReceiptItems.all().then(visible), payments: async () => await singleReceiptPayments() ? receiptPaymentRows(await receipts()) : storage.salesReceiptPayments.all().then(visible), syncs: () => storage.salesReceiptSyncs.all().then(visible) };
}

